  [32, 'adds each token field of a round that reports to the running total'],
  [36, 'starts the total from the first round that reports'],
  [40, 'keeps the total when a round reports nothing'],
  [44, 'stays undefined while no round has reported'],
];
for (const [line, name] of adds) {
  t += '\n- Folding statement for ' + name + ' ([validated by: ' + name + '](../../src/orchestration/orchestratorHelpers.test.ts#L' + line + ')).';
}
console.log('after:', JSON.stringify(statementCoverage(t)));
console.log('tier/expected:', coverageTier(statementCoverage(t).testable, statementCoverage(t).linked), expectedStatus(coverageTier(statementCoverage(t).testable, statementCoverage(t).linked)));
for (const s of linksForStatements(t).slice(-4)) console.log(JSON.stringify({line: s.statement.line, links: s.testLinks.map(l => ({path: resolveLinkPath(l.path, 'specs/hal-engine-config-hooks/spec.md'), line: l.line}))}));
"

